import numpy as np
from scipy.integrate import quad
from core.sieve import generate_primes
from core.arithmetic_functions import prime_constellation_counts, cramer_random_primes

SCALES = [100_000, 200_000, 350_000, 500_000, 1_000_000]
KS = [2, 3, 4]

def hl_integral(N, k):
    val, _ = quad(lambda t: 1.0/(np.log(t)**k), 2, N, limit=200)
    return val

def count_tuple(mask, offs):
    m = mask.copy()
    for h in offs:
        m[h:] &= mask[:-h] if h > 0 else mask
    return int(m.sum())

def tuple_counts_from_primes(P, N):
    mask = np.zeros(N + 9, dtype=bool)
    mask[P[P <= N]] = True
    return {
        2: count_tuple(mask, [2]),
        3: count_tuple(mask, [2, 6]),
        4: count_tuple(mask, [2, 6, 8]),
    }

# ---------- Real primes: use exact utility ratios ----------
print("=== REAL PRIMES: deficit cascade ===")
c_vals = {2: [], 3: [], 4: []}   # c_k(N) = delta_k * ln N
lam_vals = {2: [], 3: []}        # lambda_k = c_k / c_{k+1}
real_delta = {}
for N in SCALES:
    cc = prime_constellation_counts(N)
    R = {2: cc["ratio_twin_to_hl"], 3: cc["ratio_triplet026_to_hl"], 4: cc["ratio_quad_to_hl"]}
    d = {k: 1.0 - R[k] for k in KS}
    real_delta[N] = d
    lnN = np.log(N)
    ck = {k: d[k] * lnN for k in KS}
    for k in KS:
        c_vals[k].append(ck[k])
    for k in (2, 3):
        lam_vals[k].append(ck[k] / ck[k + 1])
    print(f"N={N:>9}: delta2={d[2]:.5f} delta3={d[3]:.5f} delta4={d[4]:.5f} | "
          f"c=[{ck[2]:.4f},{ck[3]:.4f},{ck[4]:.4f}] lam=[{ck[2]/ck[3]:.3f},{ck[3]/ck[4]:.3f}]")

crit1 = all(real_delta[N][k] > 0 for N in SCALES for k in KS)
cv = {k: np.std(c_vals[k]) / np.mean(c_vals[k]) for k in KS}
crit2 = all(v <= 0.35 for v in cv.values())
lam_all = lam_vals[2] + lam_vals[3]
crit3 = all(3.0 <= L <= 8.0 for L in lam_all) and \
        (np.std(lam_vals[2])/np.mean(lam_vals[2]) <= 0.30) and \
        (np.std(lam_vals[3])/np.mean(lam_vals[3]) <= 0.30)
print(f"C1 positive deficit: {'PASS' if crit1 else 'FAIL'} | C2 scale-invariance CV={cv} : {'PASS' if crit2 else 'FAIL'}")
print(f"C3 geometric cascade lam mean={np.mean(lam_all):.3f} : {'PASS' if crit3 else 'FAIL'}")

# ---------- Cramér null control (S = 1, no singular series) ----------
print("=== CRAMER CONTROL (S=1) ===")
cram_sign_ok = True
cram_devs = []
for N in SCALES:
    P = cramer_random_primes(N, seed=12345)
    cnt = tuple_counts_from_primes(P, N)
    for k in KS:
        I = hl_integral(N, k)
        Rc = cnt[k] / I
        dev = Rc - 1.0
        cram_devs.append(dev)
        if dev <= 0:
            cram_sign_ok = False
    print(f"N={N:>9}: Rcramer-1 for k=2,3,4 = "
          f"{cnt[2]/hl_integral(N,2)-1:+.5f}, {cnt[3]/hl_integral(N,3)-1:+.5f}, {cnt[4]/hl_integral(N,4)-1:+.5f}")

crit4 = cram_sign_ok and (np.mean(cram_devs) > 0)
print(f"C4 Cramer sign-opposite (R-1>0 everywhere): {'PASS' if crit4 else 'FAIL'}")

if not (crit1 and crit2 and crit3):
    print("VERDICT: FALSIFIED")
elif not crit4:
    print("VERDICT: TRIVIAL_NULL")
else:
    print("VERDICT: SUPPORTED")

