import numpy as np
from scipy.integrate import quad

def rho(u):
    if u <= 1.0:
        return 1.0
    if u <= 2.0:
        return 1.0 - np.log(u)
    def integrand(t):
        return (1.0 - np.log(t - 1.0)) / t
    val, _ = quad(integrand, 2.0, u, limit=100)
    return (1.0 - np.log(2.0)) - val

def T_pred(p, N):
    u = np.log(N / p) / np.log(p)
    delta = np.log(2) / np.log(p)
    return np.log(p) * (2.0 * rho(u) - rho(u - delta))

def _extract_smooth_count(res):
    if isinstance(res, dict):
        for key in ("smooth", "smooth_count", "count", "n_smooth",
                    "smooth_numbers", "y_smooth", "total", "value"):
            if key in res:
                return res[key]
        if len(res) == 1:
            return next(iter(res.values()))
        for key in res:
            if isinstance(key, str) and "smooth" in key.lower():
                return res[key]
        raise KeyError(f"Could not extract smooth count from dict keys: {list(res.keys())}")
    return res

EG = np.exp(-0.5772156649015329)
all_pass = True
summary = []

for N in [10**5, 10**6, 10**7, 10**8]:
    primes = generate_primes(int(N**(1/3)) + 1)
    primes = [p for p in primes if p >= 3]
    lo, hi = N**0.25, N**(1/3)
    ps = [p for p in primes if lo < p <= hi]
    if len(ps) < 3:
        print(f"N={N}: too few primes; skipping")
        continue
    T = []
    pred = []
    for p in ps:
        x = N // p
        C = (_extract_smooth_count(smooth_number_counts(x, p))
             - _extract_smooth_count(smooth_number_counts(x // 2, p)))
        T.append(2.0 * p * np.log(p) * C / N)
        pred.append(T_pred(p, N))
    T = np.array(T)
    pred = np.array(pred)
    err_ref = np.abs(T - pred)
    err_m = np.abs(T - EG)
    mae_ref = err_ref.mean()
    mae_m = err_m.mean()
    rng = np.random.default_rng(42)
    Tsh = rng.permutation(T)
    mae_ref_sh = np.abs(Tsh - pred).mean()
    cond1 = mae_ref < 0.5 * mae_m
    cond2 = mae_ref_sh >= 1.5 * mae_ref
    print(f"N={N:>9} | n_p={len(ps):3d} | MAE_ref={mae_ref:.6f} | MAE_Mertens={mae_m:.6f} | ratio={mae_m/max(mae_ref,1e-12):.2f} | MAE_shuf={mae_ref_sh:.6f} | {'PASS' if cond1 else 'FAIL'} | {'PASS' if cond2 else 'FAIL'}")
    all_pass &= (cond1 and cond2)
    summary.append((mae_ref, mae_m, mae_ref_sh))

print(f"Summary (MAE_ref, MAE_Mertens, MAE_shuf): {summary}")
if all_pass:
    print("VERDICT: SUPPORTED")
else:
    if all(m < 0.5 * mm for m, mm, _ in summary):
        print("VERDICT: TRIVIAL_NULL")
    else:
        print("VERDICT: FALSIFIED")

import numpy as np

# ---------------------------------------------------------------
# Core utilities (self-contained, vectorized implementations)
# ---------------------------------------------------------------

def generate_primes(limit: int) -> np.ndarray:
    sieve = np.ones(limit + 1, dtype=bool)
    sieve[:2] = False
    for p in range(2, int(limit ** 0.5) + 1):
        if sieve[p]:
            sieve[p * p::p] = False
    return np.nonzero(sieve)[0]


def compute_modular_transitions(primes, mod=10) -> dict:
    residues = np.unique(primes % mod).tolist()
    idx = {r: i for i, r in enumerate(residues)}
    k = len(residues)
    counts = [[0] * k for _ in range(k)]
    prev = None
    for p in primes:
        r = int(p) % mod
        if prev is not None:
            counts[idx[prev]][idx[r]] += 1
        prev = r
    total = sum(sum(row) for row in counts)
    matrix = [[c / total if total else 0.0 for c in row] for row in counts]
    expected_uniform = 1.0 / k
    return {"residues": residues, "transition_matrix": matrix,
            "transition_counts": counts, "expected_uniform": expected_uniform}


def goldbach_partition_counts(limit: int) -> dict:
    primes = generate_primes(limit)
    pset = np.zeros(limit + 1, dtype=bool)
    pset[primes] = True
    counts = {}
    evens = np.arange(4, limit + 1, 2)
    for n in evens:
        half = primes[primes <= n // 2]
        partners = n - half
        c = int(np.count_nonzero(pset[partners]))
        counts[int(n)] = c
    return counts


_ZETA_ZERO_CACHE = None

def get_zeta_zeros(count: int) -> list:
    global _ZETA_ZERO_CACHE
    if _ZETA_ZERO_CACHE is None:
        # cached first zeros (rounded values, sufficient for diagnostics)
        _ZETA_ZERO_CACHE = [14.134725, 21.022040, 25.010858, 30.424876,
                            32.935062, 37.586178, 40.918719, 43.327073,
                            48.005151, 49.773832]
    return _ZETA_ZERO_CACHE[:min(count, 3000)]


def mobius_sieve(limit) -> np.ndarray:
    mu = np.ones(limit + 1, dtype=int)
    is_prime = np.ones(limit + 1, dtype=bool)
    is_prime[:2] = False
    for p in range(2, limit + 1):
        if is_prime[p]:
            is_prime[2 * p::p] = False
            mu[p::p] *= -1
            if p * p <= limit:
                mu[p * p::p * p] = 0
    return mu


def mertens_function(limit) -> np.ndarray:
    return np.cumsum(mobius_sieve(limit))


def liouville_sieve(limit) -> np.ndarray:
    lam = np.ones(limit + 1, dtype=int)
    lam[0] = 0
    for p in range(2, int(limit ** 0.5) + 1):
        if lam[p] != 0:  # p prime (unmarked by smaller prime powers)
            pass
    # direct construction: lam[n] = (-1)^total number of prime factors
    lam = np.zeros(limit + 1, dtype=int)
    lam[1] = 1
    omega = np.zeros(limit + 1, dtype=int)
    for p in range(2, limit + 1):
        if omega[p] == 0:  # p is prime
            for m in range(p, limit + 1, p):
                omega[m] += 1
    lam[1:] = (-1) ** omega[1:]
    return lam


def sum_liouville(limit) -> np.ndarray:
    return np.cumsum(liouville_sieve(limit))


def largest_prime_factor(limit) -> np.ndarray:
    lpf = np.zeros(limit + 1, dtype=np.int64)
    for n in range(2, limit + 1):
        if lpf[n] == 0:  # n is prime
            lpf[n::n] = n
    return lpf


def smooth_number_counts(limit, y_bound) -> dict:
    lpf = largest_prime_factor(limit)
    counts = {}
    for y in y_bound:
        counts[y] = int(np.sum(lpf[2:] <= y))
    return counts


def chebyshev_prime_race(limit, mod, r_lead, r_trail) -> dict:
    primes = generate_primes(limit)
    lead = int(np.sum(primes % mod == r_lead))
    trail = int(np.sum(primes % mod == r_trail))
    return {"lead_count": lead, "trail_count": trail,
            "bias": lead - trail, "total": lead + trail}


def prime_constellation_counts(limit) -> dict:
    primes = generate_primes(limit)
    pset = np.zeros(limit + 10, dtype=bool)
    pset[primes] = True
    twins = cousins = sexy = t026 = t046 = quad = 0
    for p in primes:
        p2 = p + 2 in pset
        p4 = p + 4 in pset
        p6 = p + 6 in pset
        p8 = p + 8 in pset
        if p2:
            twins += 1
        if p4:
            cousins += 1
        if p6:
            sexy += 1
        if p2 and p6:
            t026 += 1
        if p4 and p6:
            t046 += 1
        if p2 and p6 and p8:
            quad += 1
    return {"twins_0_2": twins, "cousins_0_4": cousins, "sexy_0_6": sexy,
            "triplets_0_2_6": t026, "triplets_0_4_6": t046,
            "quadruplets_0_2_6_8": quad}


def cramer_random_primes(limit, seed=42) -> np.ndarray:
    rng = np.random.default_rng(seed)
    density = 1.0 / np.log(np.arange(2, limit + 1))
    mask = rng.random(limit - 1) < density
    return np.nonzero(mask)[0] + 2


# ---------------------------------------------------------------
# Conjecture under test: Chebyshev's bias — primes congruent to 3 mod 4
# lead primes congruent to 1 mod 4 across all scales, and the bias
# grows (in absolute count) with scale, unlike a random (Cramér)
# baseline which should show no systematic bias.
# ---------------------------------------------------------------

def run_scale(limit):
    race = chebyshev_prime_race(limit, 4, 3, 1)
    bias = race["bias"]
    total = race["total"]
    # binomial z-score: is bias significantly different from 0?
    z = bias / np.sqrt(total) if total > 0 else 0.0
    # null baseline: Cramér random primes
    rnd = cramer_random_primes(limit, seed=42 + limit)
    rnd_bias = int(np.sum(rnd % 4 == 3) - np.sum(rnd % 4 == 1))
    rnd_z = rnd_bias / np.sqrt(len(rnd)) if len(rnd) > 0 else 0.0
    passed = (bias > 0) and (abs(z) > 2.0)
    print(f"  scale N={limit:>8}: 3mod4={race['lead_count']:>6} "
          f"1mod4={race['trail_count']:>6} bias={bias:>6} z={z:+.3f} | "
          f"null bias={rnd_bias:>6} null_z={rnd_z:+.3f} -> "
          f"{'PASS' if passed else 'FAIL'}")
    return passed, z, rnd_z


def main():
    print("Conjecture: Chebyshev bias — primes ≡ 3 (mod 4) lead primes ≡ 1 (mod 4)")
    print("            at every scale, with significance vs. Cramér null baseline.\n")

    scales = [10_000, 100_000, 1_000_000]
    results = []
    for n in scales:
        results.append(run_scale(n))

    print()
    real_passes = sum(1 for p, _, _ in results if p)
    null_passes = sum(1 for _, z, rz in results if rz > 2.0)
    all_pass = real_passes == len(results)
    null_clean = null_passes == 0

    print(f"Real-prime scales passing: {real_passes}/{len(results)}")
    print(f"Null-baseline scales spuriously 'passing': {null_passes}/{len(results)}")

    # explicit conditional branches for both verdicts
    if all_pass and null_clean:
        print("VERDICT: SUPPORTED")
    elif not all_pass and null_clean:
        print("VERDICT: FALSIFIED")
    else:
        print("VERDICT: TRIVIAL_NULL")


if __name__ == "__main__":
    main()

