import numpy as np
from core.zeta_harmonics import get_zeta_zeros

# Load zeta zeros and unfold
gammas = np.array(get_zeta_zeros(3000))
x = gammas / (2*np.pi) * np.log(gammas / (2*np.pi)) - gammas / (2*np.pi) + 7/8

def spectral_form_factor(x, tau):
    N = len(x)
    return np.abs(np.sum(np.exp(2j*np.pi*tau*x)))**2 / N

def shuffled_ff(x, tau, seed=42):
    rng = np.random.default_rng(seed)
    N = len(x)
    s = np.diff(x)
    s_shuff = rng.permutation(s)
    x_shuff = np.concatenate(([x[0]], x[0] + np.cumsum(s_shuff)))
    return spectral_form_factor(x_shuff, tau)

Ns = [60, 120, 240, 480, 960, 1920]
taus = [0.25, 0.5]
results = {}

for N in Ns:
    step = max(1, N // 2)
    starts = range(0, len(x) - N + 1, step)
    k_zeta = {tau: [] for tau in taus}
    k_shuff = {tau: [] for tau in taus}
    for start in starts:
        window = x[start:start+N]
        for tau in taus:
            k_zeta[tau].append(spectral_form_factor(window, tau))
            k_shuff[tau].append(shuffled_ff(window, tau, seed=start))
    for tau in taus:
        results[(N, tau, 'zeta')] = np.mean(k_zeta[tau])
        results[(N, tau, 'shuff')] = np.mean(k_shuff[tau])

all_pass = True
trivial = False

for N in Ns:
    for tau in taus:
        z = results[(N, tau, 'zeta')]
        s = results[(N, tau, 'shuff')]
        # GUE band: relaxed for small N, tight for N>=240
        if N >= 240:
            tol = 0.1
        else:
            tol = 0.2
        target = tau
        cond_zeta = abs(z - target) <= tol
        cond_shuff = s >= 0.9
        cond = cond_zeta and cond_shuff
        print(f"N={N:4d}, tau={tau:.2f}: K_zeta={z:.4f} (target {target:.2f}±{tol:.2f}), K_shuff={s:.4f} -> {'PASS' if cond else 'FAIL'}")
        if not cond:
            all_pass = False
        # Check for trivial null: if zeta and shuffled are both high (not separated)
        if z >= 0.7 and s >= 0.7:
            trivial = True

if trivial:
    print("VERDICT: TRIVIAL_NULL")
elif all_pass:
    print("VERDICT: SUPPORTED")
else:
    print("VERDICT: FALSIFIED")

