import numpy as np

def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(np.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def generate_primes(limit):
    """Generate all primes up to limit using sieve of Eratosthenes."""
    if limit < 2:
        return np.array([], dtype=np.int64)

    sieve = np.ones(limit + 1, dtype=bool)
    sieve[0:2] = False

    for i in range(2, int(np.sqrt(limit)) + 1):
        if sieve[i]:
            sieve[i*i::i] = False

    return np.where(sieve)[0]

def compute_prime_gaps(primes):
    """Compute gaps between consecutive primes."""
    return np.diff(primes)

def compute_spectral_coupling(primes, gamma, mod=10):
    """Compute spectral gap-residue coupling for all transitions."""
    primes = primes[primes > mod]
    N = len(primes)

    gaps = compute_prime_gaps(primes)
    mean_gap = np.mean(gaps)
    centered_gaps = gaps - mean_gap

    residues = primes % mod
    cos_weights = np.cos(gamma * np.log(primes[:-1]))
    weighted_gaps = centered_gaps * cos_weights

    coprime_residues = [1, 3, 7, 9]
    psi_dict = {}

    for r in coprime_residues:
        for s in coprime_residues:
            mask = (residues[:-1] == r) & (residues[1:] == s)
            psi_sum = np.sum(weighted_gaps[mask])
            psi_value = psi_sum / np.sqrt(N)
            psi_dict[(r, s)] = psi_value

    return psi_dict

