# Function to generate primes up to a limit
def generate_primes(limit):
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for start in range(2, int(limit**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, limit + 1, start):
                sieve[multiple] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

# Function to compute modular transitions
def compute_modular_transitions(primes, mod):
    residues = [p % mod for p in primes]
    transition_matrix = np.zeros((mod, mod))
    for i in range(len(residues) - 1):
        transition_matrix[residues[i], residues[i + 1]] += 1
    return {
        'residues': list(range(mod)),
        'transition_matrix': transition_matrix,
        'expected_uniform': 1 / (mod - 1)
    }

# Define quadratic and non-quadratic residues modulo 30
quadratic_residues = [1, 11, 19, 29]
