# Map residues to their indices in the transition matrix
def residue_indices(residues):
    return {res: idx for idx, res in enumerate(residues)}

# Function to get transition probability
def get_transition_probability(a, b, transition_matrix, residue_indices):
    return transition_matrix[residue_indices[a]][residue_indices[b]] / sum(transition_matrix[residue_indices[a]])

# Function to test the refined hypothesis
def test_refined_hypothesis(primes, mod, epsilon):
    transitions = compute_modular_transitions(primes, mod)
    residues = transitions['residues']
    transition_matrix = transitions['transition_matrix']
    residue_indices_map = residue_indices(residues)

    count = 0
    total_pairs = len(quadratic_residues) * len(non_quadratic_residues)

    for a in quadratic_residues:
        for b in non_quadratic_residues:
            p_a_to_b = get_transition_probability(a, b, transition_matrix, residue_indices_map)
            p_b_to_a = get_transition_probability(b, a, transition_matrix, residue_indices_map)
            if abs(p_a_to_b - p_b_to_a) <= epsilon:
                count += 1

    percentage = count / total_pairs
    return percentage

